'use strict';

/**
* Test whether every element in a one-dimensional single-precision floating-point ndarray is falsy.
*
* @module @stdlib/blas/ext/base/ndarray/snone
*
* @example
* import Float32Vector from '@stdlib/ndarray/vector/float32';
* import snone from '@stdlib/blas/ext/base/ndarray/snone';
*
* var x = new Float32Vector( [ 0.0, 0.0, 1.0, 1.0 ] );
*
* var v = snone( [ x ] );
* // returns false
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var snone;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	snone = main;
} else {
	snone = tmp;
}


// EXPORTS //

export default snone;
