'use strict';

/**
* Test whether at least one element in a one-dimensional double-precision floating-point ndarray is truthy.
*
* @module @stdlib/blas/ext/base/ndarray/dany
*
* @example
* import Float64Vector from '@stdlib/ndarray/vector/float64';
* import dany from '@stdlib/blas/ext/base/ndarray/dany';
*
* var x = new Float64Vector( [ 0.0, 0.0, 1.0, 1.0 ] );
*
* var v = dany( [ x ] );
* // returns true
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var dany;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dany = main;
} else {
	dany = tmp;
}


// EXPORTS //

export default dany;
