'use strict';

/**
* Multiply each element in an input one-dimensional double-precision floating-point ndarray by a scalar constant and assign the results to elements in a one-dimensional double-precision floating-point output ndarray.
*
* @module @stdlib/blas/ext/base/ndarray/dwax
*
* @example
* import Float64Vector from '@stdlib/ndarray/vector/float64';
* import scalar2ndarray from '@stdlib/ndarray/from-scalar';
* import dwax from '@stdlib/blas/ext/base/ndarray/dwax';
*
* var x = new Float64Vector( [ -2.0, 1.0, 3.0, -5.0 ] );
* var w = new Float64Vector( [ 0.0, 0.0, 0.0, 0.0 ] );
*
* var alpha = scalar2ndarray( 5.0, {
*     'dtype': 'float64'
* });
*
* var out = dwax( [ x, w, alpha ] );
* // returns <ndarray>[ -10.0, 5.0, 15.0, -25.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var dwax;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dwax = main;
} else {
	dwax = tmp;
}


// EXPORTS //

export default dwax;
