'use strict';

/**
* Multiply each element in a one-dimensional single-precision floating-point ndarray by a scalar constant and add a scalar constant to each result.
*
* @module @stdlib/blas/ext/base/ndarray/saxpb
*
* @example
* import Float32Vector from '@stdlib/ndarray/vector/float32';
* import scalar2ndarray from '@stdlib/ndarray/from-scalar';
* import saxpb from '@stdlib/blas/ext/base/ndarray/saxpb';
*
* var x = new Float32Vector( [ -2.0, 1.0, 3.0, -5.0 ] );
*
* var alpha = scalar2ndarray( 5.0, {
*     'dtype': 'float32'
* });
*
* var beta = scalar2ndarray( 3.0, {
*     'dtype': 'float32'
* });
*
* var out = saxpb( [ x, alpha, beta ] );
* // returns <ndarray>[ -7.0, 8.0, 18.0, -22.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var saxpb;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	saxpb = main;
} else {
	saxpb = tmp;
}


// EXPORTS //

export default saxpb;
