'use strict';

// MODULES //

import ndarraylike2scalar from '@stdlib/ndarray/base/ndarraylike2scalar';
import numelDimension from '@stdlib/ndarray/base/numel-dimension';
import getStride from '@stdlib/ndarray/base/stride';
import getOffset from '@stdlib/ndarray/base/offset';
import getData from '@stdlib/ndarray/base/data-buffer';
import { ndarray as strided } from './../../../../../ext/base/gsome';


// MAIN //

/**
* Tests whether a one-dimensional ndarray contains at least `k` truthy elements.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray specifying the minimum number of truthy elements.
*
* -   The function explicitly treats `NaN` values as falsy.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {boolean} boolean indicating whether the input ndarray contains at least `k` truthy elements
*
* @example
* import vector from '@stdlib/ndarray/vector/ctor';
* import scalar2ndarray from '@stdlib/ndarray/from-scalar';
*
* var x = vector( [ 0.0, 0.0, 1.0, 2.0 ], 'generic' );
*
* var k = scalar2ndarray( 2, {
*     'dtype': 'generic'
* });
*
* var v = gsome( [ x, k ] );
* // returns true
*/
function gsome( arrays ) {
	var x = arrays[ 0 ];
	var k = ndarraylike2scalar( arrays[ 1 ] );
	return strided( numelDimension( x, 0 ), k, getData( x ), getStride( x, 0 ), getOffset( x ) ); // eslint-disable-line max-len
}


// EXPORTS //

export default gsome;
