'use strict';

/**
* Return the index of the last falsy element in a double-precision floating-point strided array.
*
* @module @stdlib/blas/ext/base/dlast-index-of-falsy
*
* @example
* import Float64Array from '@stdlib/array/float64';
* import dlastIndexOfFalsy from '@stdlib/blas/ext/base/dlast-index-of-falsy';
*
* var x = new Float64Array( [ 1.0, 2.0, 3.0, 0.0, 4.0, 0.0, -1.0, 3.0 ] );
*
* var idx = dlastIndexOfFalsy( x.length, x, 1 );
* // returns 5
*
* @example
* import Float64Array from '@stdlib/array/float64';
* import dlastIndexOfFalsy from '@stdlib/blas/ext/base/dlast-index-of-falsy';
*
* var x = new Float64Array( [ 1.0, 2.0, 3.0, 0.0, 4.0, 0.0, -1.0, 3.0 ] );
*
* var idx = dlastIndexOfFalsy.ndarray( x.length, x, 1, 0 );
* // returns 5
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var dlastIndexOfFalsy;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dlastIndexOfFalsy = main;
} else {
	dlastIndexOfFalsy = tmp;
}


// EXPORTS //

export default dlastIndexOfFalsy;

// exports: { "ndarray": "dlastIndexOfFalsy.ndarray" }
