'use strict';

/**
* Replace double-precision floating-point strided array elements equal to `NaN` with a specified scalar constant.
*
* @module @stdlib/blas/ext/base/dfill-nan
*
* @example
* import Float64Array from '@stdlib/array/float64';
* import dfillNaN from '@stdlib/blas/ext/base/dfill-nan';
*
* var x = new Float64Array( [ NaN, NaN, 1.0, NaN ] );
*
* dfillNaN( x.length, 0.0, x, 1 );
* // x => <Float64Array>[ 0.0, 0.0, 1.0, 0.0 ]
*
* @example
* import Float64Array from '@stdlib/array/float64';
* import dfillNaN from '@stdlib/blas/ext/base/dfill-nan';
*
* var x = new Float64Array( [ NaN, NaN, 1.0, NaN ] );
*
* dfillNaN.ndarray( x.length, 0.0, x, 1, 0 );
* // x => <Float64Array>[ 0.0, 0.0, 1.0, 0.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var dfillNaN;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dfillNaN = main;
} else {
	dfillNaN = tmp;
}


// EXPORTS //

export default dfillNaN;

// exports: { "ndarray": "dfillNaN.ndarray" }
