'use strict';

/**
* Subtract a scalar constant from each element in a one-dimensional double-precision floating-point ndarray.
*
* @module @stdlib/blas/ext/base/ndarray/dxsa
*
* @example
* import Float64Vector from '@stdlib/ndarray/vector/float64';
* import scalar2ndarray from '@stdlib/ndarray/from-scalar';
* import dxsa from '@stdlib/blas/ext/base/ndarray/dxsa';
*
* var x = new Float64Vector( [ -2.0, 1.0, 3.0, -5.0 ] );
*
* var alpha = scalar2ndarray( 5.0, {
*     'dtype': 'float64'
* });
*
* var out = dxsa( [ x, alpha ] );
* // returns <ndarray>[ -7.0, -4.0, -2.0, -10.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var dxsa;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dxsa = main;
} else {
	dxsa = tmp;
}


// EXPORTS //

export default dxsa;
