'use strict';

/**
* Compute the sum of all elements in a one-dimensional single-precision floating-point ndarray using an improved Kahan–Babuška algorithm.
*
* @module @stdlib/blas/ext/base/ndarray/ssumkbn
*
* @example
* import Float32Vector from '@stdlib/ndarray/vector/float32';
* import ssumkbn from '@stdlib/blas/ext/base/ndarray/ssumkbn';
*
* var x = new Float32Vector( [ 1.0, 3.0, 4.0, 2.0 ] );
*
* var v = ssumkbn( [ x ] );
* // returns 10.0
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var ssumkbn;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	ssumkbn = main;
} else {
	ssumkbn = tmp;
}


// EXPORTS //

export default ssumkbn;
