'use strict';

/**
* Fill a one-dimensional single-precision floating-point ndarray with linearly spaced numeric elements which increment by `1` starting from one.
*
* @module @stdlib/blas/ext/base/ndarray/sone-to
*
* @example
* import Float32Vector from '@stdlib/ndarray/vector/float32';
* import soneTo from '@stdlib/blas/ext/base/ndarray/sone-to';
*
* var x = new Float32Vector( [ 0.0, 0.0, 0.0, 0.0 ] );
* // returns <ndarray>[ 0.0, 0.0, 0.0, 0.0 ]
*
* var out = soneTo( [ x ] );
* // returns <ndarray>[ 1.0, 2.0, 3.0, 4.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var soneTo;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	soneTo = main;
} else {
	soneTo = tmp;
}


// EXPORTS //

export default soneTo;
